[CmdletBinding()]
param(
    [ValidateSet("all", "pci1710l", "pci1762", "pci6208v", "cp118u_i")]
    [string]$Server = "all"
)

$ErrorActionPreference = "Stop"
$root = Split-Path -Parent $MyInvocation.MyCommand.Path
$workspaceRoot = Split-Path -Parent $root
$pythonCandidates = @(
    (Join-Path $workspaceRoot "sim_hardware\.venv\Scripts\python.exe"),
    (Join-Path $workspaceRoot "sim_hardware\venv\Scripts\python.exe")
)
$python = $pythonCandidates | Where-Object { Test-Path -LiteralPath $_ } | Select-Object -First 1
if (-not $python) { throw "No local Python environment found under sim_hardware" }

$serverIds = if ($Server -eq "all") {
    @("pci1710l", "pci1762", "pci6208v", "cp118u_i")
} else {
    @($Server)
}

try {
    foreach ($serverId in $serverIds) {
        $serverRoot = Join-Path $root "servers\$serverId"
        $env:PYTHONPATH = Join-Path $serverRoot "app\src"
        $env:HARDWAREHARNESS_SERVER_CONFIG = Join-Path $serverRoot "server.example.json"
        Write-Host "[test] $serverId"
        & $python -m unittest discover -s (Join-Path $serverRoot "app\tests") -p "test_*.py"
        if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
    }
}
finally {
    Remove-Item Env:PYTHONPATH -ErrorAction SilentlyContinue
    Remove-Item Env:HARDWAREHARNESS_SERVER_CONFIG -ErrorAction SilentlyContinue
}

"""Subprocess adapter for hwcli_pci1710l (DAQNavi JSON-line CLI)."""

from __future__ import annotations

import json
import logging
import os
import subprocess
import threading
from pathlib import Path
from typing import Any, Optional

log = logging.getLogger(__name__)

_proc: Optional[subprocess.Popen[str]] = None
_lock = threading.Lock()

# The simulated board, used only when HARDWARE_DRY_RUN is set. See
# _dry_run_dispatch below for what is and is not modelled.
_dry_open = False
_dry_safe_do_mask = 0
_dry_do = 0  # bit i = DO i driven high
_dry_ai_cfg: dict[int, dict[str, Any]] = {}  # channel -> {signal_type, value_range}
# Same table as signal_name() in native/hwcli_pci1710l.cpp.
_SIGNAL_NAMES = {0: "SingleEnded", 1: "Differential", 2: "PseudoDifferential"}


class SdkError(RuntimeError):
    pass


def dry_run() -> bool:
    return os.environ.get("HARDWARE_DRY_RUN", "").strip() in ("1", "true", "TRUE", "yes")


def resolve_hwcli() -> Optional[Path]:
    env = os.environ.get("PCI1710L_HWCLI_PATH", os.environ.get("HWCLI_PATH", "")).strip()
    if env:
        p = Path(env)
        if p.is_file():
            return p
    here = Path(__file__).resolve()
    candidates = [
        here.parents[2] / "native" / "build" / "Release" / "hwcli_pci1710l.exe",
        here.parents[2] / "native" / "build" / "Debug" / "hwcli_pci1710l.exe",
        here.parents[2] / "native" / "build" / "hwcli_pci1710l.exe",
        here.parents[2] / "native" / "build" / "hwcli_pci1710l",
    ]
    for c in candidates:
        if c.is_file():
            return c
    return None


def start() -> None:
    global _proc
    if dry_run():
        return
    with _lock:
        if _proc is not None and _proc.poll() is None:
            return
        path = resolve_hwcli()
        if path is None:
            raise SdkError(
                "hwcli_pci1710l not found. Build native/ (cmake -S native -B native/build && "
                "cmake --build native/build) or set PCI1710L_HWCLI_PATH."
            )
        log.info("Starting hwcli: %s", path)
        _proc = subprocess.Popen(
            [str(path)],
            stdin=subprocess.PIPE,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            encoding="utf-8",
            errors="replace",
            bufsize=1,
        )


def stop() -> None:
    global _proc
    with _lock:
        if _proc is None:
            return
        try:
            if _proc.poll() is None and _proc.stdin:
                _proc.stdin.write(json.dumps({"cmd": "close"}) + "\n")
                _proc.stdin.flush()
        except Exception:  # noqa: BLE001
            pass
        try:
            _proc.terminate()
            _proc.wait(timeout=3)
        except Exception:  # noqa: BLE001
            try:
                _proc.kill()
            except Exception:  # noqa: BLE001
                pass
        _proc = None


def call(cmd: dict[str, Any]) -> dict[str, Any]:
    if dry_run():
        return _dry_run_dispatch(cmd)

    start()
    assert _proc is not None and _proc.stdin and _proc.stdout
    line = json.dumps(cmd, ensure_ascii=False)
    with _lock:
        if _proc.poll() is not None:
            raise SdkError(f"hwcli exited early with code {_proc.returncode}")
        _proc.stdin.write(line + "\n")
        _proc.stdin.flush()
        resp = _proc.stdout.readline()
        if not resp:
            err_tail = ""
            if _proc.stderr:
                err_tail = _proc.stderr.read()[:500]
            raise SdkError(f"hwcli returned empty response. stderr={err_tail!r}")
    try:
        return json.loads(resp)
    except json.JSONDecodeError as exc:
        raise SdkError(f"hwcli non-JSON response: {resp!r}") from exc


def _dry_run_dispatch(cmd: dict[str, Any]) -> dict[str, Any]:
    """A 16-DO / 16-DI / 16-AI card in about sixty lines.

    This used to echo the command back for `read_bit`, `set_level` and friends,
    which proves the protocol works and nothing else: driving DO1 high and then
    reading it back came out with no `value` key at all, so a graph that checks
    its own stimulus could not pass without hardware. The payload shapes below
    are the ones native/hwcli_pci1710l.cpp prints, field for field -- a dry run
    whose shape differs from the real board is worse than no dry run, because
    the graph it validates is not the graph that will run.

    Modelled: the open gate, the DO register (which is what a readback of your
    own stimulus depends on), and the configure_ai-before-read_voltage
    precondition, because a graph that forgets it fails on the bench and should
    fail here too.

    Not modelled: DI and the AI voltage itself. Those come from whatever is
    wired to the connector, and inventing a level or a reading would be
    inventing the unit under test. DI reads false; AI reads 0.0 V.
    """
    global _dry_open, _dry_safe_do_mask, _dry_do
    c = cmd.get("cmd")

    if c == "open":
        _dry_open = True
        _dry_safe_do_mask = int(cmd.get("safe_do_mask", 0))
        _dry_do = _dry_safe_do_mask
        _dry_ai_cfg.clear()
        return {
            "ok": True,
            "reachable": True,
            "message": "DRY_RUN opened",
            "data": {
                "description": cmd.get("description", "PCI-1710L,BID#15"),
                "safe_do_mask": _dry_safe_do_mask,
            },
        }
    if c in ("ping", "enumerate", "self_test"):
        return {"ok": True, "reachable": True, "message": f"DRY_RUN {c}", "data": cmd}

    # Everything below touches the board, and the real CLI answers "Not open"
    # for all of it. Keeping that gate is the point: `open` is the graph
    # author's job now, and a dry run that forgave a missing one would let the
    # mistake through to the bench.
    if not _dry_open:
        return {"ok": False, "reachable": True, "message": "DRY_RUN Not open", "data": None}

    if c == "probe_features":
        return {
            "ok": True,
            "reachable": True,
            "message": "DRY_RUN features",
            "data": {
                "channelCountMax": 16,
                "connectionTypes": [{"name": "SingleEnded", "enum": 0}],
                "valueRanges": [{"enum": 1, "label": "+/- 10 V", "min": -10, "max": 10}],
            },
        }
    if c == "configure_ai":
        channel = int(cmd.get("channel", 0))
        signal_type = int(cmd.get("signal_type", 0))
        value_range = int(cmd.get("value_range", 1))
        _dry_ai_cfg[channel] = {"signal_type": signal_type, "value_range": value_range}
        return {
            "ok": True, "reachable": True, "message": "DRY_RUN AI channel configured",
            "data": {"channel": channel, "signal_type": signal_type,
                     "value_range": value_range,
                     "signal": _SIGNAL_NAMES.get(signal_type, "SingleEnded")},
        }
    if c == "read_voltage":
        channel = int(cmd.get("channel", 0))
        cfg = _dry_ai_cfg.get(channel)
        if cfg is None:
            return {"ok": False, "reachable": True,
                    "message": "DRY_RUN AI channel not configured — call configure_ai first",
                    "data": None}
        return {
            "ok": True, "reachable": True, "message": f"DRY_RUN AI{channel} = 0 V",
            "data": {"channel": channel, "volts": 0.0, "raw": 0,
                     "signal": _SIGNAL_NAMES.get(cfg["signal_type"], "SingleEnded"),
                     "value_range": cfg["value_range"]},
        }
    if c == "set_level":
        channel = int(cmd.get("channel", 0))
        level = bool(cmd.get("level", False))
        if level:
            _dry_do |= 1 << channel
        else:
            _dry_do &= ~(1 << channel)
        return {"ok": True, "reachable": True, "message": "DRY_RUN DO set (actuates)",
                "data": {"channel": channel, "level": level}}
    if c == "read_bit":
        channel = int(cmd.get("channel", 0))
        kind = str(cmd.get("kind", "DI"))
        value = bool(_dry_do >> channel & 1) if kind.upper() == "DO" else False
        return {"ok": True, "reachable": True, "message": "DRY_RUN read_bit",
                "data": {"kind": kind, "channel": channel, "value": value}}
    if c == "safe_state":
        _dry_do = _dry_safe_do_mask
        return {"ok": True, "reachable": True, "message": "DRY_RUN DO safe_state applied",
                "data": {"safe_do_mask": _dry_safe_do_mask}}
    if c == "close":
        _dry_do = _dry_safe_do_mask
        _dry_open = False
        return {"ok": True, "reachable": True, "message": "DRY_RUN Closed after safe_state",
                "data": {"open": False}}

    return {"ok": False, "reachable": False, "message": f"DRY_RUN unknown {c}", "data": None}

"""MCP stdio server for Advantech PCI-1710L (16 AI + 16 DI + 16 DO)."""

from __future__ import annotations

import atexit
import logging
import os
import sys
from typing import Any, Optional

from mcp.server.mcpserver import MCPServer

from hardwareharness_remote import pci1710l_sdk as sdk
from hardwareharness_remote.result import err, ok

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s %(levelname)s [%(name)s] %(message)s",
    stream=sys.stderr,
)
log = logging.getLogger("advantech_pci1710l")

mcp = MCPServer(
    name="advantech-pci1710l",
    version="0.1.0",
    instructions=(
        "Advantech PCI-1710L: 16 AI + 16 DI + 16 DO (no AO on L model). "
        "Bench description default PCI-1710L,BID#15. "
        "configure_ai before read_voltage. set_level ACTUATES DO. "
        "close/safe_state applies SAFE_DO_MASK (default 0). self_test never writes DO."
    ),
)

_open = False

# Common ValueRange enums from this card's probe (static table for tool docs).
VALUE_RANGE_HINT = {
    1: "±10 V",
    2: "±5 V",
    3: "±2.5 V",
    4: "±1.25 V",
    12: "±625 mV",
    7: "0~10 V",
    8: "0~5 V",
    9: "0~2.5 V",
    10: "0~1.25 V",
}


def _default_desc() -> str:
    return os.environ.get("ADVANTECH_PCI1710L_DESC", "PCI-1710L,BID#15")


def _safe_mask() -> int:
    raw = os.environ.get("SAFE_DO_MASK", "0")
    try:
        return int(raw, 0) & 0xFFFF
    except ValueError:
        return 0


def _wrap(resp: dict[str, Any]) -> dict[str, Any]:
    if "ok" in resp:
        return resp
    return err("malformed CLI response", data=resp)


@mcp.tool()
def info() -> dict[str, Any]:
    """Server identity, hwcli path, env (no hardware access)."""
    return ok(
        "Advantech PCI-1710L MCP",
        data={
            "board": "PCI-1710L",
            "hwcli": str(sdk.resolve_hwcli()) if sdk.resolve_hwcli() else None,
            "dry_run": sdk.dry_run(),
            "open": _open,
            "description": _default_desc(),
            "safe_do_mask": _safe_mask(),
            "value_range_hint": VALUE_RANGE_HINT,
            "signal_type_hint": {"0": "SingleEnded", "1": "Differential"},
            "env": {
                "ADVANTECH_PCI1710L_DESC": os.environ.get("ADVANTECH_PCI1710L_DESC", "PCI-1710L,BID#15"),
                "SAFE_DO_MASK": os.environ.get("SAFE_DO_MASK", "0"),
                "PCI1710L_HWCLI_PATH": os.environ.get("PCI1710L_HWCLI_PATH", os.environ.get("HWCLI_PATH")),
                "HARDWARE_DRY_RUN": os.environ.get("HARDWARE_DRY_RUN", ""),
            },
        },
    )


@mcp.tool()
def open(description: Optional[str] = None, safe_do_mask: Optional[int] = None) -> dict[str, Any]:
    """Bind AI/DI/DO controllers. Does not write DO until safe_state/set_level."""
    global _open
    if _open:
        return err("Already open", reachable=True)
    desc = description or _default_desc()
    mask = _safe_mask() if safe_do_mask is None else int(safe_do_mask) & 0xFFFF
    try:
        resp = _wrap(sdk.call({"cmd": "open", "description": desc, "safe_do_mask": mask}))
        if resp.get("ok"):
            _open = True
        return resp
    except sdk.SdkError as exc:
        return err(str(exc), reachable=False)


@mcp.tool()
def close() -> dict[str, Any]:
    """Apply safe DO mask then release. ACTUATES DO."""
    global _open
    try:
        resp = _wrap(sdk.call({"cmd": "close"}))
        _open = False
        return resp
    except sdk.SdkError as exc:
        _open = False
        return err(str(exc), reachable=False)


@mcp.tool()
def probe_features() -> dict[str, Any]:
    """Read AI features: channel counts, connection types, value ranges."""
    try:
        return _wrap(sdk.call({"cmd": "probe_features"}))
    except sdk.SdkError as exc:
        return err(str(exc), reachable=False)


@mcp.tool()
def configure_ai(channel: int, signal_type: int = 0, value_range: int = 1) -> dict[str, Any]:
    """Configure one AI channel before reading. signal_type 0=SE 1=Diff; value_range is enum."""
    if channel < 0 or channel > 15:
        return err("channel must be 0..15", reachable=True)
    try:
        return _wrap(
            sdk.call(
                {
                    "cmd": "configure_ai",
                    "channel": channel,
                    "signal_type": signal_type,
                    "value_range": value_range,
                }
            )
        )
    except sdk.SdkError as exc:
        return err(str(exc), reachable=False)


@mcp.tool()
def read_voltage(channel: int) -> dict[str, Any]:
    """Read one AI channel in volts. Requires prior configure_ai."""
    if channel < 0 or channel > 15:
        return err("channel must be 0..15", reachable=True)
    try:
        return _wrap(sdk.call({"cmd": "read_voltage", "channel": channel}))
    except sdk.SdkError as exc:
        return err(str(exc), reachable=False)


@mcp.tool()
def read_bit(channel: int, kind: str = "DI") -> dict[str, Any]:
    """Read DI or DO bit (0..15)."""
    if channel < 0 or channel > 15:
        return err("channel must be 0..15", reachable=True)
    if kind.upper() not in ("DI", "DO"):
        return err("kind must be DI or DO", reachable=True)
    try:
        return _wrap(sdk.call({"cmd": "read_bit", "channel": channel, "kind": kind.upper()}))
    except sdk.SdkError as exc:
        return err(str(exc), reachable=False)


@mcp.tool()
def set_level(channel: int, level: bool) -> dict[str, Any]:
    """Set one DO bit. ACTUATES digital output."""
    if channel < 0 or channel > 15:
        return err("channel must be 0..15", reachable=True)
    try:
        return _wrap(sdk.call({"cmd": "set_level", "channel": channel, "level": level}))
    except sdk.SdkError as exc:
        return err(str(exc), reachable=False)


@mcp.tool()
def safe_state() -> dict[str, Any]:
    """Write DO to safe_do_mask and verify. ACTUATES."""
    try:
        return _wrap(sdk.call({"cmd": "safe_state"}))
    except sdk.SdkError as exc:
        return err(str(exc), reachable=False)


@mcp.tool()
def self_test(description: Optional[str] = None) -> dict[str, Any]:
    """Bind + read AI features. Never writes DO or samples for actuation."""
    desc = description or _default_desc()
    try:
        return _wrap(sdk.call({"cmd": "self_test", "description": desc}))
    except sdk.SdkError as exc:
        return err(str(exc), reachable=False)


def _atexit() -> None:
    global _open
    if _open:
        try:
            close()
        except Exception as exc:  # noqa: BLE001
            log.warning("atexit close: %s", exc)
    sdk.stop()


atexit.register(_atexit)


def main() -> None:
    mcp.run(transport="stdio")


if __name__ == "__main__":
    main()

