from __future__ import annotations

import asyncio
import json
import os
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any, Callable

from hardwareharness_remote.compat import install

install()

from hardwareharness_remote import cp118u, pci1710l, pci1762, pci6208v, pinouts  # noqa: E402


class AdapterError(RuntimeError):
    def __init__(self, message: str, *, category: str = "device_error", details: Any = None):
        super().__init__(message)
        self.category = category
        self.details = details


def _unwrap(result: dict[str, Any]) -> Any:
    if result.get("ok"):
        return result.get("data")
    category = "device_unreachable" if not result.get("reachable", False) else "device_error"
    raise AdapterError(result.get("message", "Hardware operation failed"), category=category, details=result.get("data"))


@dataclass
class HardwareAdapter:
    hardware_id: str
    manufacturer: str
    model: str
    capabilities: list[str]
    open_fn: Callable[..., dict[str, Any]]
    safe_fn: Callable[..., dict[str, Any]] | None
    close_fn: Callable[..., dict[str, Any]]
    operations: dict[str, Callable[..., dict[str, Any]]]
    pinout: pinouts.Pinout
    lock: asyncio.Lock = field(default_factory=asyncio.Lock)

    async def _call(self, fn: Callable[..., dict[str, Any]], **kwargs: Any) -> Any:
        async with self.lock:
            return _unwrap(await asyncio.to_thread(fn, **kwargs))

    async def open(self) -> Any:
        return await self._call(self.open_fn)

    async def safe(self) -> Any:
        return {"safe": True, "action": "none"} if self.safe_fn is None else await self._call(self.safe_fn)

    async def close(self) -> Any:
        return await self._call(self.close_fn)

    async def invoke(self, operation: str, **kwargs: Any) -> Any:
        fn = self.operations.get(operation)
        if fn is None:
            raise AdapterError(f"Unsupported operation: {operation}", category="invalid_argument")
        return await self._call(fn, **kwargs)


def _server_config() -> dict[str, Any]:
    path = os.environ.get("HARDWAREHARNESS_SERVER_CONFIG")
    if not path:
        raise RuntimeError("HARDWAREHARNESS_SERVER_CONFIG is required")
    return json.loads(Path(path).read_text(encoding="utf-8-sig"))


def build_adapters() -> list[HardwareAdapter]:
    config = _server_config()
    server_id = config["serverId"]
    hardware_id = config["hardwareId"]
    definitions: dict[str, dict[str, Any]] = {
        "PCI1710L_MCP": dict(manufacturer="Advantech", model="PCI-1710L", capabilities=["analog_input", "digital_input", "digital_output"], open_fn=pci1710l.open, safe_fn=pci1710l.safe_state, close_fn=pci1710l.close, operations={"configure_ai": pci1710l.configure_ai, "read_voltage": pci1710l.read_voltage, "read_bit": pci1710l.read_bit, "set_level": pci1710l.set_level, "safe_state": pci1710l.safe_state}),
        "PCI1762_MCP": dict(manufacturer="Advantech", model="PCI-1762", capabilities=["relay_output", "digital_input"], open_fn=pci1762.open, safe_fn=pci1762.safe_state, close_fn=pci1762.close, operations={"set_relay": pci1762.set_relay, "set_bank": pci1762.set_bank, "read_bit": pci1762.read_bit, "safe_state": pci1762.safe_state}),
        "PCI6208V_MCP": dict(manufacturer="ADLINK", model="PCI-6208V", capabilities=["analog_output"], open_fn=pci6208v.open, safe_fn=pci6208v.safe_state, close_fn=pci6208v.close, operations={"set_voltage": pci6208v.set_voltage, "read_last": pci6208v.read_last, "safe_state": pci6208v.safe_state}),
        "CP118U_I_MCP": dict(manufacturer="Moxa", model="CP-118U-I", capabilities=["serial_rs232_rs422_rs485"], open_fn=cp118u.open, safe_fn=None, close_fn=cp118u.close, operations={"configure_port": cp118u.configure_port, "write_text": cp118u.write_text, "write_hex": cp118u.write_hex, "read_rx": cp118u.read_rx, "clear_rx": cp118u.clear_rx, "flush": cp118u.flush, "get_line_status": cp118u.get_line_status}),
    }
    selected = definitions.get(server_id)
    if selected is None:
        raise RuntimeError(f"Unsupported serverId: {server_id}")
    if selected["manufacturer"] != config["manufacturer"] or selected["model"] != config["model"]:
        raise RuntimeError("server.json manufacturer/model does not match the implemented driver")
    return [HardwareAdapter(hardware_id=hardware_id, pinout=pinouts.get_pinout_data(hardware_id), **selected)]

from __future__ import annotations

import asyncio
import logging
import time
from dataclasses import dataclass, field
from datetime import UTC, datetime
from typing import Any, Literal

from hardwareharness_remote.adapters import AdapterError, HardwareAdapter, build_adapters
from hardwareharness_remote.pinouts import Pinout
from hardwareharness_remote.occupancy import OccupancyRegistry

HardwareState = Literal["initializing", "open", "unreachable", "faulted", "closing", "closed"]

log = logging.getLogger("hardwareharness_remote.lifecycle")


def iso_now() -> str:
    return datetime.now(UTC).isoformat()


@dataclass
class HardwareRuntime:
    adapter: HardwareAdapter
    state: HardwareState = "initializing"
    last_error: dict[str, Any] | None = None
    retry_index: int = 0
    next_retry: float = 0.0
    operation_lock: asyncio.Lock = field(default_factory=asyncio.Lock)

    def snapshot(self) -> dict[str, Any]:
        return {
            "hardwareId": self.adapter.hardware_id,
            "manufacturer": self.adapter.manufacturer,
            "model": self.adapter.model,
            "capabilities": self.adapter.capabilities,
            "state": self.state,
            "health": "ok" if self.state == "open" else self.state,
            "lastError": self.last_error,
        }


class HardwareManager:
    def __init__(self) -> None:
        self.runtimes = {adapter.hardware_id: HardwareRuntime(adapter) for adapter in build_adapters()}
        self.draining = False
        self.startup_complete = False
        self._watchdog: asyncio.Task[None] | None = None
        self._start_lock = asyncio.Lock()
        self.occupancy = OccupancyRegistry()

    def _runtime(self, hardware_id: str) -> HardwareRuntime:
        runtime = self.runtimes.get(hardware_id)
        if runtime is None:
            raise AdapterError(f"Unknown hardwareId: {hardware_id}", category="invalid_argument")
        return runtime

    async def start(self) -> None:
        async with self._start_lock:
            if self.startup_complete and self._watchdog and not self._watchdog.done():
                return
            self.draining = False
            for hardware_id in sorted(self.runtimes):
                await self._open_runtime(self.runtimes[hardware_id])
            self.startup_complete = True
            self._watchdog = asyncio.create_task(self._watchdog_loop(), name="hardware-watchdog")

    async def _open_runtime(self, runtime: HardwareRuntime) -> None:
        runtime.state = "initializing"
        try:
            await runtime.adapter.open()
            await runtime.adapter.safe()
            runtime.state = "open"
            runtime.last_error = None
            runtime.retry_index = 0
        except Exception as exc:
            category = exc.category if isinstance(exc, AdapterError) else "device_error"
            runtime.state = "unreachable"
            runtime.last_error = {"category": category, "message": str(exc), "at": iso_now()}
            delays = (5, 10, 30)
            runtime.next_retry = time.monotonic() + delays[min(runtime.retry_index, len(delays) - 1)]
            runtime.retry_index += 1
            log.exception("Failed to open %s", runtime.adapter.hardware_id)

    async def stop(self) -> None:
        self.draining = True
        if self._watchdog:
            self._watchdog.cancel()
            try:
                await self._watchdog
            except asyncio.CancelledError:
                pass
        for hardware_id in sorted(self.runtimes, reverse=True):
            runtime = self.runtimes[hardware_id]
            async with runtime.operation_lock:
                runtime.state = "closing"
                try:
                    await runtime.adapter.safe()
                except Exception:
                    log.exception("Safe state failed during shutdown: %s", hardware_id)
                finally:
                    self.occupancy.clear_locked(hardware_id)
                try:
                    await runtime.adapter.close()
                    runtime.state = "closed"
                except Exception as exc:
                    runtime.state = "faulted"
                    runtime.last_error = {"category": "device_error", "message": str(exc), "at": iso_now()}
        self.startup_complete = False
        self._watchdog = None

    async def _watchdog_loop(self) -> None:
        while True:
            now = time.monotonic()
            for runtime in self.runtimes.values():
                async with runtime.operation_lock:
                    try:
                        await self.occupancy.expire_locked(runtime)
                    except Exception:
                        log.exception("Safe state failed for expired occupancy lease: %s", runtime.adapter.hardware_id)
                    if runtime.state == "unreachable" and now >= runtime.next_retry and not self.draining:
                        await self._open_runtime(runtime)
            await asyncio.sleep(1)

    async def invoke(self, hardware_id: str, operation: str, occupancy_lease_id: str | None, **kwargs: Any) -> Any:
        if self.draining:
            raise AdapterError("Server is draining", category="service_unavailable")
        runtime = self._runtime(hardware_id)
        async with runtime.operation_lock:
            if self.draining:
                raise AdapterError("Server is draining", category="service_unavailable")
            if runtime.state != "open":
                raise AdapterError(f"Hardware is not available: {runtime.state}", category="device_unreachable", details=runtime.snapshot())
            await self.occupancy.require_locked(runtime, occupancy_lease_id)
            return await runtime.adapter.invoke(operation, **kwargs)

    async def occupancy_action(self, hardware_id: str, action: str, holder_id: str | None = None, holder_label: str | None = None, lease_id: str | None = None) -> dict[str, Any]:
        runtime = self._runtime(hardware_id)
        async with runtime.operation_lock:
            return await self.occupancy.action_locked(runtime, action, holder_id, holder_label, lease_id)

    def get_pinout(self, hardware_id: str) -> Pinout:
        return self._runtime(hardware_id).adapter.pinout.model_copy(deep=True)

    def list_hardware(self) -> list[dict[str, Any]]:
        return [self.runtimes[key].snapshot() for key in sorted(self.runtimes)]

    def get_hardware(self, hardware_id: str) -> dict[str, Any]:
        return self._runtime(hardware_id).snapshot()

