def _source() -> dict[str, Any]:
    frame = inspect.currentframe()
    try:
        while frame:
            filename = frame.f_code.co_filename
            if filename != __file__:
                return {"path": filename, "line": frame.f_lineno}
            frame = frame.f_back
        return {}
    finally:
        del frame


def _event(kind: str, data: dict[str, Any], **identity: Any) -> None:
    _transport.request("event", {"type": kind, "spanId": _span.get(), "data": data, **identity})


def call(
    hardware_id: str,
    tool_name: str,
    arguments: dict[str, Any],
    *,
    timeout_ms: int | None = None,
) -> Any:
    """Invoke one declared active hardware tool through the platform's existing gates."""
    return _transport.request(
        "call",
        {
            "hardwareId": hardware_id,
            "toolName": tool_name,
            "arguments": arguments,
            "timeoutMs": timeout_ms,
            "parentSpanId": _span.get(),
            "source": _source(),
        },
    )


async def acall(
    hardware_id: str,
    tool_name: str,
    arguments: dict[str, Any],
    *,
    timeout_ms: int | None = None,
) -> Any:
    """Asynchronous equivalent of :func:`call`; no hardware request is replayed."""
    return await asyncio.to_thread(
        _transport.request,
        "call",
        {
            "hardwareId": hardware_id,
            "toolName": tool_name,
            "arguments": arguments,
            "timeoutMs": timeout_ms,
            "parentSpanId": _span.get(),
            "source": _source(),
        },
    )


class _Step:
    def __init__(self, name: str) -> None:
        if not isinstance(name, str) or not name.strip():
            raise ValueError("Step name must be a non-empty string")
        self.name = name
        self.token: contextvars.Token[str | None] | None = None
        self.started = 0.0
        self.span_id = ""

    def __enter__(self) -> _Step:
        if self.token is not None:
            raise RuntimeError("Use a separate step block for each concurrent invocation")
        self.span_id = uuid.uuid4().hex
        _event(
            "step.started",
            {"source": _source()},
            spanId=self.span_id,
            parentSpanId=_span.get(),
            name=self.name,
        )
        self.token = _span.set(self.span_id)
        self.started = time.perf_counter()
        return self

    def __exit__(
        self,
        kind: type[BaseException] | None,
        error: BaseException | None,
        tb: TracebackType | None,
    ) -> None:
        assert self.token is not None, "Step exit requires an entered block"
        data: dict[str, Any] = {
            "status": "failed" if error else "succeeded",
            "durationMs": round((time.perf_counter() - self.started) * 1000),
        }
        if error:
            data["error"] = {
                "message": str(error),
                "traceback": "".join(traceback.format_exception(kind, error, tb)),
            }
        try:
            _event("step.completed", data, name=self.name)
        finally:
            _span.reset(self.token)
            self.token = None

    async def __aenter__(self) -> _Step:
        return self.__enter__()

    async def __aexit__(
        self,
        kind: type[BaseException] | None,
        error: BaseException | None,
        tb: TracebackType | None,
    ) -> None:
        self.__exit__(kind, error, tb)

    def __call__(self, function: Callable[P, R]) -> Callable[P, R]:
        if inspect.iscoroutinefunction(function):

            @functools.wraps(function)
            async def async_wrapper(*args: P.args, **kwargs: P.kwargs) -> Any:
                async with _Step(self.name):
                    return await function(*args, **kwargs)

            return cast(Callable[P, R], async_wrapper)

        @functools.wraps(function)
        def wrapper(*args: P.args, **kwargs: P.kwargs) -> R:
            with _Step(self.name):
                return function(*args, **kwargs)

        return wrapper


def step(name: str) -> _Step:
    """Mark a business step as a decorator or a sync/async context manager."""
    return _Step(name)


def log(message: str, *, level: str = "info", fields: dict[str, Any] | None = None) -> None:
    _event("log", {"message": message, "level": level, "fields": fields or {}, "source": _source()})


def measurement(name: str, value: float | int, *, unit: str | None = None) -> None:
    _event("measurement", {"name": name, "value": value, "unit": unit, "source": _source()})


def attachment(path: str | Path, *, name: str | None = None, media_type: str | None = None) -> None:
    _transport.request(
        "attachment",
        {
            "path": str(Path(path).resolve()),
            "name": name,
            "mediaType": media_type,
            "spanId": _span.get(),
        },
    )

"""Private runner transport. Credentials never form part of the user API."""

from __future__ import annotations

import json
import os
import threading
from typing import Any
from urllib.error import HTTPError, URLError
from urllib.request import Request, urlopen

_cancelled = threading.Event()
_cancel_delivered = threading.Event()


class HardwareHarnessError(RuntimeError):
    def __init__(self, category: str, message: str, details: Any = None) -> None:
        super().__init__(message)
        self.category, self.details = category, details


class RunCancelled(BaseException):
    """Cooperative cancellation must survive ordinary application exception handlers."""


def check_cancelled() -> None:
    if _cancelled.is_set() and not _cancel_delivered.is_set():
        _cancel_delivered.set()
        raise RunCancelled("Run cancelled")


def request(operation: str, data: dict[str, Any]) -> Any:
    if operation == "call":
        check_cancelled()
    url = os.environ.get("HARDWAREHARNESS_WORKER_URL")
    token = os.environ.get("HARDWAREHARNESS_WORKER_TOKEN")
    if not url or not token:
        raise RuntimeError("This code must be launched by HardwareHarness")
    payload = json.dumps({"operation": operation, "data": data}, allow_nan=False).encode("utf-8")
    message = Request(
        url,
        data=payload,
        headers={"Authorization": f"Bearer {token}", "Content-Type": "application/json"},
        method="POST",
    )
    timeout = max(15.0, float(data.get("timeoutMs") or 30_000) / 1000 + 5)
    try:
        with urlopen(message, timeout=timeout) as response:
            result = json.loads(response.read())
    except HTTPError as error:
        try:
            result = json.loads(error.read())
        except (ValueError, OSError) as malformed:
            raise HardwareHarnessError(
                "unavailable", "HardwareHarness rejected the request"
            ) from malformed
    except (URLError, TimeoutError, OSError) as error:
        raise HardwareHarnessError(
            "unavailable", "HardwareHarness connection lost; remote operation result is unknown"
        ) from error
    if not isinstance(result, dict):
        raise HardwareHarnessError("invalid_response", "Invalid HardwareHarness response")
    if "error" in result:
        failure = result["error"]
        raise HardwareHarnessError(failure["category"], failure["message"], failure.get("details"))
    return result.get("result")

